new.pkey:
struct PKey {
    i256 v[8 * (EPSDEG + 1)];
    PKey() { for (int i = 0; i < 8 * (EPSDEG + 1); i++) v[i] = i256((i128)0); }
    bool operator==(const PKey& o) const {
        for (int i = 0; i < 8 * (EPSDEG + 1); i++) if (!(v[i] == o.v[i])) return false;
        return true;
    }
};

new.planek:
static inline i256 gcdOfElems(const FieldElem* es, int n) {
    i256 g = i256((i128)0);
    for (int e = 0; e < n; e++)
        for (int k = 0; k <= EPSDEG; k++) {
            g = igcd256(g, es[e].c[k].p);
            g = igcd256(g, es[e].c[k].q);
        }
    return g;
}
static inline void divElem(FieldElem& x, const i256& g) {
    for (int k = 0; k <= EPSDEG; k++) {
        x.c[k].p = idiv256_exact(x.c[k].p, g);
        x.c[k].q = idiv256_exact(x.c[k].q, g);
    }
}
static PKey planeKey(int pid) {
    FieldElem e[4] = {planes[pid].a, planes[pid].b, planes[pid].c, planes[pid].d};
    // Content divided out over every eps coefficient AT ONCE: scaling a plane by
    // a positive integer leaves the plane unchanged, but doing it per-coefficient
    // would rescale eps degrees against each other and change the plane.
    i256 g = gcdOfElems(e, 4);
    if (i256IsZero(g)) g = i256((i128)1);
    for (int t = 0; t < 4; t++) divElem(e[t], g);
    int s = feSign(e[0]); if (s == 0) s = feSign(e[1]); if (s == 0) s = feSign(e[2]);
    if (s < 0) for (int t = 0; t < 4; t++) e[t] = -e[t];
    PKey k;
    int i = 0;
    for (int t = 0; t < 4; t++)
        for (int m = 0; m <= EPSDEG; m++) { k.v[i++] = e[t].c[m].p; k.v[i++] = e[t].c[m].q; }
    return k;
}

new.mag:
for (int k = 0; k <= EPSDEG; k++) {
