new.fetos:
static std::string coefToStr(const Coef& v) {
    if (i256IsZero(v.q)) return i256ToStr(v.p);
    return i256ToStr(v.p) + "+" + i256ToStr(v.q) + "r" + std::to_string(g_d);
}
static std::string feToStr(const FieldElem& v) {
    std::string s;
    int hi = 0;
    for (int k = 0; k <= EPSDEG; k++) if (!coefIsZero(v.c[k])) hi = k;
    for (int k = 0; k <= hi; k++) {
        if (k) s += "|";
        s += coefToStr(v.c[k]);
    }
    return s;
}
